.featured-card {
  position: relative;
}

.badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
}

@keyframes pulse {
  from { opacity: 0.65; }
  to { opacity: 1; }
}

.badge {
  animation: pulse 1s ease-in-out infinite alternate;
}

lessons.code:
.badge {
  animation: pulse 1s infinite;
}

lessons.solution:
.badge {
  animation: pulse 1s infinite;
