@media (prefers-reduced-motion: reduce) {
  .badge {
    animation: none;
  }
}

:root {
  --accent: #2563eb;
}

.lab-page {
  max-width: 72rem;
  margin: 0 auto;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.preview-card {
  padding: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.75rem;
}

.cta-button:hover {
  background-color: var(--accent);
}

@media (max-width: 700px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
}
